/** Body-shape picker previews (90×80 PNG, data URI). */
export const QR_BODY_PREVIEW_PNG: Record<string, string> = {
  'square': 'data:image/png;base64,',
  'mosaic': 'data:image/png;base64,',
  'dot': 'data:image/png;base64,',
  'circle': 'data:image/png;base64,',
  'circle-zebra': 'data:image/png;base64,',
  'circle-zebra-vertical': 'data:image/png;base64,',
  'circular': 'data:image/png;base64,',
  'edge-cut': 'data:image/png;base64,',
  'edge-cut-smooth': 'data:image/png;base64,',
  'japnese': 'data:image/png;base64,',
  'knob': 'data:image/png;base64,',
  'knob-smooth': 'data:image/png;base64,',
  'leaf': 'data:image/png;base64,',
  'pointed': 'data:image/png;base64,',
  'pointed-edge-cut': 'data:image/png;base64,',
  'pointed-in': 'data:image/png;base64,',
  'pointed-in-smooth': 'data:image/png;base64,',
  'pointed-smooth': 'data:image/png;base64,',
  'round': 'data:image/png;base64,',
  'rounded-in': 'data:image/png;base64,',
  'rounded-in-smooth': 'data:image/png;base64,',
  'rounded-pointed': 'data:image/png;base64,',
  'star': 'data:image/png;base64,',
  'diamond': 'data:image/png;base64,',
};

/** HTML <img> for a body-style picker tile. */
export function bodyPreviewImgHtml(id: string, size = 44): string {
  const src = QR_BODY_PREVIEW_PNG[id];
  if (!src) return '';
  const h = Math.round((size * 80) / 90);
  return `<img src="${src}" width="${size}" height="${h}" alt="" draggable="false" />`;
}
